list_shipping_rules.code:
var response = await client.ShippingRules.ListShippingRulesAsync(
    new Dictionary<string, object?> { ["zone_id"] = 5, ["method"] = "flat_rate", ["handling_cost"] = "without_handling", ["sort"] = "name", ["order"] = "asc" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var rule in ((IReadOnlyList<object?>)body["shipping_rules"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{rule["id"]} {rule["name"]} {rule["description"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");

